from manim import *

class Hydrogen(Scene):
    def construct(self):
        # Create a hydrogen atom with an electron orbiting around it
        proton = self.create_proton()
        electron = self.create_electron()

        orbit = Circle(color=BLUE).scale(0.5)
        orbit.move_to(proton)

        electron.move_to(orbit.point_from_proportion(0))
        self.play(FadeIn(proton), FadeIn(orbit), FadeIn(electron))
        self.play(Rotate(electron, angle=2*PI, about_point=proton.get_center()), run_time=2, rate_func=smooth)
        self.wait()

    def create_proton(self) -> Mobject:
        # Proton represented by a circle with a 'P+'
        return Circle(radius=0.15, color=RED).set_fill(RED, opacity=1).add(
            Tex("P$^+$", color=WHITE).scale(0.7)
        )

    def create_electron(self) -> Mobject:
        # Electron represented by a small dot
        return Dot(radius=0.05, color=WHITE)

# Additional function to animate the electron along a custom path
def electron_orbit_path(electron: Mobject, orbit: Mobject, run_time: float) -> Animation:
    def update_electron(mob, dt):
        mob.move_to(orbit.point_from_proportion((mob.time_elapsed / run_time) % 1))
        mob.time_elapsed += dt

    electron.time_elapsed = 0
    return UpdateFromFunc(electron, update_electron)
