from manim import *

class Gather(Animation):
    def __init__(self, mobject, dot_radius=0.05, dot_number=100, **kwargs):
        super().__init__(mobject, **kwargs)
        self.dot_radius = dot_radius
        self.dot_number = dot_number
        self.starting_dots = VGroup(
            *[Dot(radius=self.dot_radius) for _ in range(self.dot_number)]
        )
        self.create_starting_dots()

    def begin(self):
        self.mobject.set_opacity(0)
        for dot in self.starting_dots:
            dot.move_to(dot.initial_position)
        self.mobject.add(self.starting_dots)
        super().begin()

    def create_starting_dots(self):
        mobject_center = self.mobject.get_center()
        for dot in self.starting_dots:
            dot.shift_vector = np.random.uniform(-4, 4, 3)
            dot.initial_position = mobject_center + dot.shift_vector
            dot.set_opacity(0)

    def interpolate_mobject(self, alpha):
        alpha = self.rate_func(alpha)  # manually apply rate function
        if alpha <= 0.5:
            self.starting_dots.set_opacity(2 * alpha)
            for dot in self.starting_dots:
                dot.move_to(dot.initial_position + (0.5 - alpha) * dot.shift_vector)
        else:
            self.starting_dots.set_opacity(2 * (1 - alpha))
            self.mobject.set_opacity(2 * (alpha - 0.5), family=False)

    def clean_up_from_scene(self, scene):
        super().clean_up_from_scene(scene)
        scene.remove(self.starting_dots)

class CustomGatherAnimationExample(Scene):
    def construct(self):
        square = Square(color=BLUE, fill_opacity=1).scale(2)
        self.add(square)
        self.wait()
        self.play(Gather(square, dot_number=200, run_time=4))
        self.wait()
