class HydrogenGridScene(Scene):
    def construct(self):
        grid = self.create_hydrogen_grid(5, 5)
        self.play(FadeIn(grid))
        self.wait(2)

    def create_hydrogen_grid(self, rows: int, cols: int) -> VGroup:
