        for i in range(rows):
            for j in range(cols):
                hydrogen = self.create_hydrogen().move_to(np.array([i - rows // 2, j - cols // 2, 0]))
                group.add(hydrogen)
        return group

    def create_hydrogen(self) -> Mobject:
        return Circle(radius=0.2, color=WHITE).set_fill(color=WHITE, opacity=0.5).add(
            Tex('H').set_color(BLACK).scale(0.5)
        )
